// Let's inspect which businesses in the 177 results have customer reviews / star ratings!
const reviewAnalysis = await browserjs(tabId, async () => {
  // We can fetch the profile pages of the top 30 businesses or all businesses and check for customer reviews
  // First, let's gather unique profile URLs from the 177 results
  const res = await fetch("/search?filter_distance=5&find_country=USA&find_latlng=40.757371%2C-73.980887&find_loc=New%20York%2C%20NY&find_text=Used%20Car%20Dealers&page=1&sort=Rating");
  const text = await res.text();
  const match = text.match(/window\.__PRELOADED_STATE__\s*=\s*({.*?});/s);
  const page1 = match ? JSON.parse(match[1]).searchResult?.results : [];

  // Let's check page 1 items first
  const checks = [];
  for (const r of page1) {
    try {
      const pRes = await fetch(r.reportUrl);
      const pText = await pRes.text();
      // Look for schema.org review or aggregateRating
      const ldMatch = pText.match(/<script type="application\/ld\+json">(.*?)<\/script>/s);
      let ratingValue = null;
      let reviewCount = null;
      if (ldMatch) {
        try {
          const ld = JSON.parse(ldMatch[1]);
          const localBiz = Array.isArray(ld) ? ld.find(x => x['@type'] === 'LocalBusiness') : ld;
          if (localBiz && localBiz.aggregateRating) {
            ratingValue = localBiz.aggregateRating.ratingValue;
            reviewCount = localBiz.aggregateRating.reviewCount;
          }
          // Also check additionalProperty for customer reviews
          if (localBiz && localBiz.additionalProperty) {
            const cr = localBiz.additionalProperty.find(p => p.name === 'BBB Customer Reviews');
            if (cr) reviewCount = reviewCount || cr.value;
          }
        } catch(e) {}
      }

      // Check text for star rating or reviews
      const starMatch = pText.match(/class="[^"]*star[^"]*"[^>]*aria-label="([^"]+)"/i) || pText.match(/([0-9](\.[0-9]+)?)\s+out of 5 stars/i) || pText.match(/Average of ([0-9]+) Customer Reviews/i);

      // Check isMultiLocation
      const isMultiMatch = pText.match(/"isMultiLocation":(true|false)/);
      const totalLocMatch = pText.match(/"totalLocations":(\d+)/);

      checks.push({
        name: r.businessName,
        rating: r.rating,
        url: r.reportUrl,
        aggregateRatingValue: ratingValue,
        reviewCount: reviewCount,
        starMatch: starMatch ? starMatch[0] : null,
        isMultiLocation: isMultiMatch ? isMultiMatch[1] : null,
        totalLocations: totalLocMatch ? totalLocMatch[1] : null
      });
    } catch(e) {
      checks.push({ name: r.businessName, error: e.message });
    }
  }
  return checks;
});

