const cardsData = await browserjs(tabId, () => {
  // Let's find all business cards.
  // Notice in BBB, cards have h3 links or specific classes
  const cards = [];
  const h3Elements = Array.from(document.querySelectorAll('h3')).filter(h => {
    return h.querySelector('a') && !h.closest('#filter-section') && !h.closest('aside') && !h.closest('nav');
  });

  for (const h3 of h3Elements) {
    const link = h3.querySelector('a');
    // Find the enclosing card container
    let card = h3;
    while (card && !card.classList.contains('dtm-search-result') && !card.getAttribute('data-entity-id') && card.parentElement && card.parentElement.tagName !== 'MAIN') {
      card = card.parentElement;
    }

    // Get text, links, star ratings, review counts, etc.
    const text = card.innerText;
    const ratingEl = card.querySelector('[class*="rating"], [class*="Rating"], [aria-label*="rating"], [aria-label*="Rating"], [aria-label*="star"], [aria-label*="Star"]');
    const stars = card.querySelectorAll('svg[class*="star"], .bds-rating, [class*="review"]');

    cards.push({
      name: h3.textContent.trim(),
      url: link ? link.href : null,
      fullText: text
    });
  }

  return cards;
});

