const profileChecks = await browserjs(tabId, async () => {
  const urls = [
    "/us/ny/new-york/profile/used-car-dealers/easy-way-auto-0121-87146116",
    "/us/ny/new-york/profile/used-car-dealers/manhattan-motorcars-inc-0121-62626",
    "/us/ny/new-york/profile/used-car-dealers/manhattan-motors-0121-16861",
    "/us/ny/baldwin/profile/used-car-dealers/showroom-auto-llc-0121-156130"
  ];

  const results = [];
  for (const url of urls) {
    try {
      const res = await fetch(url);
      const text = await res.text();
      // Look for locations, rating, customer reviews
      const parser = new DOMParser();
      const doc = parser.parseFromString(text, 'text/html');

      const bbbRating = doc.querySelector('[class*="rating-letter"], .dtm-rating')?.textContent?.trim();
      const stars = doc.querySelector('[class*="star"], [class*="customer-review"]')?.textContent?.trim();

      // Look for other locations
      const locationLinks = Array.from(doc.querySelectorAll('a')).filter(a => 
        a.textContent.toLowerCase().includes('location') || a.href.includes('addressId')
      ).map(a => ({ text: a.textContent.trim(), href: a.href }));

      const headings = Array.from(doc.querySelectorAll('h1, h2, h3, h4')).map(h => h.textContent.trim());

      results.push({
        url,
        title: doc.title,
        bbbRating,
        locationLinks,
        hasLocationsHeading: headings.filter(h => h.toLowerCase().includes('location')),
        textSnippet: doc.body.innerText.slice(0, 500)
      });
    } catch (e) {
      results.push({ url, error: e.message });
    }
  }
  return results;
});

