const checkProfile = async (url) => {
  const fullUrl = url.startsWith('http') ? url : `https://www.bbb.org${url}`;
  const res = await fetch(fullUrl);
  const text = await res.text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(text, 'text/html');

  // Extract BBB Rating
  const bbbRatingEl = doc.querySelector('.dtm-rating, [class*="rating-letter"]');
  const bbbRating = bbbRatingEl ? bbbRatingEl.textContent.trim() : null;

  // Extract Customer Review Rating
  // Look for star rating or review text like "4.5/5" or "5/5" or "(X Customer Reviews)"
  const reviewEl = doc.querySelector('.dtm-reviews, [class*="customer-reviews"], [class*="CustomerReviews"]');
  const reviewText = reviewEl ? reviewEl.textContent.trim() : null;

  // Check any text containing "Customer Reviews" or "/5" or "stars"
  const bodyText = doc.body.innerText;
  const reviewMatch = bodyText.match(/([0-9](\.[0-9]+)?)\s*\/\s*5/);
  const reviewCountMatch = bodyText.match(/([0-9]+)\s+Customer Reviews?/i);

