// Fetch all pages of search results with sort=Rating and filter_distance=5
const allData = await browserjs(tabId, async () => {
  const allResults = [];

  // Total pages is around 12
  for (let page = 1; page <= 12; page++) {
    const url = `/search?filter_distance=5&find_country=USA&find_latlng=40.757371%2C-73.980887&find_loc=New%20York%2C%20NY&find_text=Used%20Car%20Dealers&page=${page}&sort=Rating`;
    try {
      const res = await fetch(url);
      const text = await res.text();
      const match = text.match(/window\.__PRELOADED_STATE__\s*=\s*({.*?});/s);
      if (match) {
        const state = JSON.parse(match[1]);
        const results = state.searchResult?.results || [];
        for (const r of results) {
          allResults.push({
            page,
            id: r.id,
            businessId: r.businessId,
            name: r.businessName,
            rating: r.rating,
            ratingScore: r.ratingScore,
            address: r.address,
            city: r.city,
            state: r.state,
            postalcode: r.postalcode,
            phone: r.phone?.[0],
            reportUrl: r.reportUrl,
            bbbMember: r.bbbMember
          });
        }
      }
    } catch (e) {
      console.error("Error page " + page, e);
    }
  }
  return allResults;
});

console.log("Total results fetched with sort=Rating:", allData.length);

// Let's also check which businesses appear more than once (i.e. multiple locations or multiple entries)
const nameCounts = {};
for (const r of allData) {
  nameCounts[r.name] = (nameCounts[r.name] || 0) + 1;
}
const multiEntries = Object.entries(nameCounts).filter(([k, v]) => v > 1);
console.log("Businesses appearing multiple times:", JSON.stringify(multiEntries, null, 2));

