  ];

  const results = [];
  for (const u of urls) {
    const res = await fetch(u);
    const html = await res.text();
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');

    // Find any element containing reviews or rating
    const reviewLinks = Array.from(doc.querySelectorAll('a, span, div, p')).filter(el => 
      el.textContent.includes('Customer Reviews') || el.textContent.includes('stars') || el.textContent.includes('/5')
    ).map(el => el.textContent.trim().replace(/\s+/g, ' ')).slice(0, 5);

