      .map(el => el.getAttribute('aria-label'));

    // Check preloaded state or digitalData
    const webDigitalDataMatch = html.match(/var webDigitalData\s*=\s*({.*?});/s);
    let digitalData = null;
    if (webDigitalDataMatch) {
      try {
        digitalData = JSON.parse(webDigitalDataMatch[1]);
      } catch(e) {}
    }

    results.push({
      url: u,
      reviewLinks,
      svgs,
      digitalData: digitalData?.business_info
    });
  }
  return results;
});

