const tabId = 1854033397;

// Fetch all 177 results' URLs first, then check their ratings/reviews
const reviewData = await browserjs(tabId, async () => {
  // 1. Get all unique business report URLs from the search results (all 12 pages)
  const reportUrls = new Set();
  const businesses = [];

  for (let page = 1; page <= 12; page++) {
    const url = `/search?filter_distance=5&find_country=USA&find_latlng=40.757371%2C-73.980887&find_loc=New%20York%2C%20NY&find_text=Used%20Car%20Dealers&page=${page}&sort=Rating`;
    const res = await fetch(url);
    const text = await res.text();
    const match = text.match(/window\.__PRELOADED_STATE__\s*=\s*({.*?});/s);
    if (match) {
      const state = JSON.parse(match[1]);
      const results = state.searchResult?.results || [];
      for (const r of results) {
        if (!reportUrls.has(r.reportUrl)) {
          reportUrls.add(r.reportUrl);
          businesses.push({
            name: r.businessName,
            reportUrl: r.reportUrl,
            bbbRating: r.rating,
            ratingScore: r.ratingScore,
            city: r.city,
            state: r.state
          });
        }
      }
    }
  }

  // 2. In parallel batches of 15, fetch their business profiles and extract reviewsComplaintsSummary & locations
  const batchSize = 15;
  const detailed = [];

  for (let i = 0; i < businesses.length; i += batchSize) {
    const batch = businesses.slice(i, i + batchSize);
    const batchPromises = batch.map(async (b) => {
      try {
        const res = await fetch(b.reportUrl);
        const text = await res.text();
        const match = text.match(/window\.__PRELOADED_STATE__\s*=\s*({.*?});/s);
        if (match) {
          const state = JSON.parse(match[1]);
          const bp = state.businessProfile || {};
          const summary = bp.reviewsComplaintsSummary || {};
          const locs = bp.dialogLocations?.results?.locations?.byId || {};
          const locList = Object.values(locs).map(l => ({
            id: l.id,
            name: l.name,
            address: l.address,
            city: l.city,
            state: l.stateProvince,
            postalCode: l.postalCode
          }));

          return {
            name: b.name,
            url: b.reportUrl,
            bbbRating: b.bbbRating,
            ratingScore: b.ratingScore,
            reviewsTotal: summary.reviewsTotal || 0,
            averageStarRating: summary.averageOfReviewStarRatings || null,
            totalLocations: bp.dialogLocations?.results?.totalLocations || 1,
            isMultiLocation: bp.isMultiLocation || false,
            locations: locList.length > 0 ? locList : [{
              address: bp.location?.postalAddress?.addressLine1,
              city: bp.location?.postalAddress?.city,
              state: bp.location?.postalAddress?.stateProvince,
              postalCode: bp.location?.postalAddress?.postalCode
            }]
          };
        }
      } catch (e) {
        return { name: b.name, url: b.reportUrl, error: e.message };
      }
    });

    const batchResults = await Promise.all(batchPromises);
    detailed.push(...batchResults);
  }

  return detailed;
});

console.log("Total unique businesses analyzed:", reviewData.length);

// Businesses with customer reviews
const withReviews = reviewData.filter(b => b.reviewsTotal > 0);
withReviews.sort((a, b) => (b.averageStarRating || 0) - (a.averageStarRating || 0) || b.reviewsTotal - a.reviewsTotal);
console.log("Businesses with reviews sorted by star rating:");
console.log(JSON.stringify(withReviews.map(b => ({
  name: b.name,
  stars: b.averageStarRating,
  reviewsCount: b.reviewsTotal,
  bbbRating: b.bbbRating,
  totalLocations: b.totalLocations,
  locations: b.locations
})), null, 2));

